import { registerStep, registerCompensation, startEngine } from '@projexlight/sdk-workflow';
registerStep('triage',     async (input) => { /* assign to adjuster */ });
registerStep('await-review', async (input, { waitForSignal }) => waitForSignal('decision'));
registerStep('settle',     async (input) => { /* sdk-payment.charge */ });
registerCompensation('settle', async (input) => { /* sdk-payment.refund */ });
startEngine({});

import { startRun } from '@projexlight/sdk-workflow';
const { run_id } = await startRun({
  tenant_id, definition_name: 'claims-fnol-pipeline',
  input: { claim_id, reporter_email, photos: [...] },
  correlation_key: claim_id,
});

await fetch(`/api/workflows/${run_id}/signal`, {
  method: 'POST',
  body: JSON.stringify({ name: 'decision', payload: { outcome: 'approve', amount_cents: 75000 } }),
});

// Pseudo-trace:
// triage     ✓
// await-review ✓ (signal: approve)
// settle     ✗ (Stripe declined)
//   → fires compensation for settle (refund) AND any prior step that registered one
//   → run terminates with status='failed'
